const ColorMapping* ColorMappings(int* count)
{
	*count = (int)(sizeof kMappings / sizeof kMappings[0]);
	return kMappings;
}

void* NewSystemColorTable()
{
	if (!UseAuroraColors())
		return NULL;		// ui_color() answers Haiku's compiled-in defaults
	server_read_only_memory* table = (server_read_only_memory*)calloc(1, sizeof(server_read_only_memory));
	if (table == NULL)
		return NULL;
	for (int32 i = 0; i < kColorWhichCount; i++)
		table->colors[i] = B_TRANSPARENT_COLOR;
	const Theme& theme = Theme::Current();
	for (const ColorMapping& m : kMappings) {
		rgb_color c;
		int32 index = color_which_to_index(m.which);
		if (index >= 0 && index < kColorWhichCount && theme.Color(m.token, &c))
			table->colors[index] = c;
	}
	return table;
}

// ---- control look settings ----------------------------------------------------------------------------------------

bool UseAuroraColors()
{
	const char* env = getenv("AURORA_COLORS");
	if (env != NULL && *env != '\0')
		return strcmp(env, "haiku") != 0;
	std::string colors;
	if (Theme::Current().String("theme.controls.colors", &colors))
		return colors != "haiku";
	return true;
}

bool UseAuroraControlLook()
{
	const char* env = getenv("AURORA_CONTROL_LOOK");
	if (env != NULL && *env != '\0')
		return strcmp(env, "haiku") != 0;
	std::string look;
	if (Theme::Current().String("theme.controls.look", &look))
		return look != "haiku";
	return true;
}

float ControlCornerRatio()
{
	double v = 0.28;
	Theme::Current().Number("theme.controls.corner_ratio", &v);
	return (float)(v < 0.0 ? 0.0 : v > 0.5 ? 0.5 : v);
}

